import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Dxeykp0S.js";const y=JSON.parse('{"title":"开学第一课：一起来感受 Python 之美","description":"","frontmatter":{},"headers":[],"relativePath":"preface.md","filePath":"preface.md","lastUpdated":1787141678000}'),l={name:"preface.md"};function h(n,e,i,p,c,s){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="开学第一课-一起来感受-python-之美" tabindex="-1">开学第一课：一起来感受 Python 之美 <a class="header-anchor" href="#开学第一课-一起来感受-python-之美" aria-label="Permalink to &quot;开学第一课：一起来感受 Python 之美&quot;">​</a></h1><h2 id="课程背景" tabindex="-1">课程背景 <a class="header-anchor" href="#课程背景" aria-label="Permalink to &quot;课程背景&quot;">​</a></h2><p>本课程从 Python 语言本身出发，通过循序渐进的阅读、实验和项目，一路学到 Python 后端工程。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>做好预备奔跑的姿势</li><li>开始爱上 Python</li><li>大概知道 Python 能做什么、为什么 AI 时代它是第一语言</li><li>写下你学习 Python 的 Flag</li></ul><h2 id="python-案例" tabindex="-1">Python 案例 <a class="header-anchor" href="#python-案例" aria-label="Permalink to &quot;Python 案例&quot;">​</a></h2><p>好的，我们开始吧。在写任何一行 Python 之前，先看看这个语言生态里那些美好的东西。依次浏览下面的项目（建议不要同时都打开）：</p><ul><li><a href="https://fastapi.tiangolo.com/" target="_blank" rel="noreferrer">FastAPI</a> —— 现代 Python Web 框架，自动生成 OpenAPI 文档，性能对标 Node.js</li><li><a href="https://github.com/Textualize/rich" target="_blank" rel="noreferrer">Rich</a> —— 在终端里渲染出富文本、表格、进度条，体验 <code>pip install rich</code> 之后的终端美学</li><li><a href="https://github.com/Textualize/textual" target="_blank" rel="noreferrer">Textual</a> —— 用 Python 写出漂亮的终端 UI（TUI）应用</li><li><a href="https://github.com/3b1b/manim" target="_blank" rel="noreferrer">Manim</a> —— 3Blue1Brown 的数学动画引擎，那些惊艳的数学视频都是 Python 生成的</li><li><a href="https://github.com/sqlalchemy/sqlalchemy" target="_blank" rel="noreferrer">SQLAlchemy</a> —— Python ORM 的事实标准，高级班的主角</li><li><a href="https://github.com/celery/celery" target="_blank" rel="noreferrer">Celery</a> —— 成熟的分布式任务队列</li><li><a href="https://github.com/httpie/cli" target="_blank" rel="noreferrer">httpie</a> —— 比 curl 人性化十倍的 HTTP 客户端，纯 Python 实现</li></ul><p>还有许多优秀的项目，不妨点进去亲自感受一下 Python 生态的魅力。</p><blockquote><p>不妨在浏览器中专门建一个收藏夹目录，叫做 <code>python-showcase</code>，把上面这些项目都放进去，当以后想找灵感的时候，不妨多看看。</p></blockquote><h2 id="python-背景知识" tabindex="-1">Python 背景知识 <a class="header-anchor" href="#python-背景知识" aria-label="Permalink to &quot;Python 背景知识&quot;">​</a></h2><p>初体验了 Python 生态，我们来系统地了解一下 Python 是什么、它的发展历史与设计哲学：</p><ul><li><a href="https://docs.python.org/zh-cn/3/tutorial/" target="_blank" rel="noreferrer">Python 官方教程（中文）</a> —— 全站最重要的资料，没有之一</li><li><a href="https://peps.python.org/pep-0020/" target="_blank" rel="noreferrer">Python 之禅（PEP 20）</a> —— 打开终端输入 <code>python -c &quot;import this&quot;</code> 也能看到</li><li><a href="http://python-history.blogspot.com/" target="_blank" rel="noreferrer">The History of Python</a> —— Guido 亲自写的 Python 发展史</li><li><a href="https://zhuanlan.zhihu.com/p/35422938" target="_blank" rel="noreferrer">Python 是如何流行起来的</a></li><li><a href="https://github.com/vinta/awesome-python" target="_blank" rel="noreferrer">awesome-python</a> —— Python 生态的全景地图</li></ul><h2 id="学习方法论" tabindex="-1">学习方法论 <a class="header-anchor" href="#学习方法论" aria-label="Permalink to &quot;学习方法论&quot;">​</a></h2><p>在接下来的学习中，我们建议：</p><ol><li><strong>建立知识连接</strong>：先弄清每个概念在 Python 中的意义；如果你熟悉其他语言，再通过对照加深理解。</li><li><strong>警惕经验陷阱</strong>：你以为一样的，往往不一样。比如 Python 的 <code>==</code> 和 <code>is</code>、列表作为默认参数的坑、<code>import</code> 的副作用。</li><li><strong>用真实项目驱动</strong>：不要停留在练习册层面，尽快用 Python 做一个自己真正会使用的小工具。</li><li><strong>读官方文档</strong>：Python 的官方文档质量极高，远超大多数语言。学会读它，比看任何二手教程都快。</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>找一个你可以记录笔记的地方（推荐在本仓库新建一个 <code>notes/</code> 目录，用 Markdown 记录），写下今天的学习笔记，包括以下内容：</p><ul><li>日期，今天的学习总用时，今天学习的目标是什么，是否达成</li><li>哪些东西今天了解得比较透彻，说说自己的理解</li><li>哪些东西今天了解到了一些，还有哪些点需要后续继续深入阅读</li><li>哪些东西今天学了之后还有很多疑问没有被解答，把问题记录下来，以待后续解决</li></ul><p>当然，今天笔记最重要的事情是：</p><p><strong>立 Flag，写下你参加 Python 学园的目标，能不能和我们一起坚持！</strong></p><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一站是<a href="/python-practices/warmup/">预备班</a>，我们会把开发环境搭好，并理解 Python 的核心思维。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://github.com/python/cpython" target="_blank" rel="noreferrer">CPython 源码</a> —— 有闲情逸致时可以逛逛</li></ul>',25)])])}const u=t(l,[["render",h]]);export{y as __pageData,u as default};
